<?php if(!empty($four['problems'])): ?><section class="card section"><h2>مسائل این تجربه</h2><?php foreach($four['problems'] as $problem): ?><div class="structured-problem"><h3><?= $this->h($problem['title']) ?></h3><?php if($problem['description']!==''): ?><div class="reading-prose"><?= $this->paragraphs($problem['description']) ?></div><?php endif; ?><div class="row"><?php foreach($problem['tags'] as $tag): ?><a class="tag" href="<?= $this->h($this->url('/experiences?issue='.$tag['id'])) ?>"><?= $this->h($tag['title']) ?></a><?php endforeach; ?></div></div><?php endforeach; ?></section><?php endif; ?>
<?php if(!empty($four['audiences'])): ?><section class="card section"><h2>مخاطبان تجربه</h2><div class="row"><?php foreach($four['audiences'] as $audience): ?><a class="tag" href="<?= $this->h($this->url('/experiences?audience='.$audience['id'])) ?>"><?= $this->h($audience['title']) ?></a><?php endforeach; ?></div></section><?php endif; ?>
<?php if(!empty($four['context']['independent'])): ?><p class="notice section">این تجربه مستقل و بدون مجموعهٔ مشخص ثبت شده است.</p><?php endif; ?>
